(function(){'use strict';
const PROFILE_KEY='safariCircleProfile',POSTS_KEY='safariCirclePosts',INTERESTS_KEY='safariCircleInterests',profileForm=document.getElementById('circleRegistrationForm'),loginForm=document.getElementById('circleLoginForm'),verificationForm=document.getElementById('circleVerificationForm'),onboarding=document.getElementById('circleOnboarding'),main=document.getElementById('circleMain'),feed=document.getElementById('circleFeed');if(!profileForm)return;
const interests=['Big cats','Elephants','Birding','Marine life','Conservation','Safari photography','Wildlife film','Field guiding','Family safari','Overlanding','Botswana','East Africa','Southern Africa','West & Central Africa','North Africa','African islands'];
const safe=value=>String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const read=(key,fallback)=>{try{const value=JSON.parse(localStorage.getItem(key)||'null');return value??fallback}catch{return fallback}};
const write=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
const initials=name=>String(name||'Safari Friend').split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();
const getProfile=()=>read(PROFILE_KEY,null),getPosts=()=>{const posts=read(POSTS_KEY,[]);return Array.isArray(posts)?posts:[]};let pendingRegistration=null;
async function authRequest(path,payload){const response=await fetch(`/api/auth/${path}`,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},credentials:'include',body:JSON.stringify(payload)});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.message||'The account service is unavailable. Please try again.');return data}
function verificationBadge(profile){return profile.verified===true?'<span class="account-trust">✓ Contact verified</span>':'<span class="account-trust pending">Verification required</span>'}
function showProfile(profile){onboarding.hidden=true;main.hidden=false;document.getElementById('circleAvatar').textContent=initials(profile.name);document.getElementById('circleProfile').innerHTML=`<div class="circle-profile-mark">${safe(initials(profile.name))}</div><h2>${safe(profile.name)}</h2><span>${safe(profile.handle?'@'+profile.handle:profile.role)}</span>${verificationBadge(profile)}<p>${safe(profile.bio,'No field introduction yet.')}</p><small>${safe(profile.home,'Home country not added')}</small>`;document.getElementById('circleProfileDetail').innerHTML=`<div class="circle-profile-detail"><div class="circle-profile-mark">${safe(initials(profile.name))}</div><div><p class="eyebrow dark">${safe(profile.role)}</p><h2>${safe(profile.name)}</h2>${profile.handle?`<p>@${safe(profile.handle)}</p>`:''}${verificationBadge(profile)}<p>${safe(profile.bio,'No field introduction yet.')}</p><small>${safe(profile.home,'Home country not added')}</small></div></div>`;renderFeed()}
function showAuth(mode){onboarding.hidden=false;main.hidden=true;onboarding.classList.toggle('circle-welcome',!mode);verificationForm.hidden=true;profileForm.hidden=mode!=='create';loginForm.hidden=mode!=='login';document.getElementById('circleCreateTab').classList.toggle('selected',mode==='create');document.getElementById('circleLoginTab').classList.toggle('selected',mode==='login');onboarding.scrollIntoView({block:'start'})}
function editProfile(){const profile=getProfile();if(!profile)return;let dialog=document.getElementById('circleEditDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='circleEditDialog';dialog.className='circle-modal';document.body.append(dialog)}dialog.innerHTML=`<div class="circle-modal-inner"><button class="circle-modal-close" type="button" aria-label="Close">×</button><p class="eyebrow dark">MY PROFILE</p><h2>Edit public profile</h2><form><label>Display name<input name="name" required maxlength="60" value="${safe(profile.name)}"></label><label>Handle<input name="handle" required maxlength="30" pattern="[A-Za-z0-9_]+" value="${safe(profile.handle)}"></label><label>Safari role<select name="role">${['Safari traveller','Photographer','Filmmaker','Guide','Researcher','Conservation practitioner','Safari enthusiast'].map(role=>`<option ${profile.role===role?'selected':''}>${role}</option>`).join('')}</select></label><label>Home country<input name="home" maxlength="60" value="${safe(profile.home)}"></label><label>About you<textarea name="bio" maxlength="240">${safe(profile.bio)}</textarea></label><button>Save profile</button><p aria-live="polite"></p></form></div>`;dialog.querySelector('.circle-modal-close').addEventListener('click',()=>dialog.close());dialog.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.target),updated={...profile,name:String(form.get('name')).trim().slice(0,60),handle:String(form.get('handle')).trim().replace(/^@/,'').slice(0,30),role:form.get('role'),home:String(form.get('home')).trim().slice(0,60),bio:String(form.get('bio')).trim().slice(0,240)};const status=event.target.querySelector('p');status.textContent='Saving…';try{await fetch('/api/circle/me',{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(updated)});write(PROFILE_KEY,updated);showProfile(updated);dialog.close()}catch{write(PROFILE_KEY,updated);showProfile(updated);dialog.close()}});dialog.showModal()}
document.getElementById('circleCreateTab').addEventListener('click',()=>showAuth('create'));document.getElementById('circleLoginTab').addEventListener('click',()=>showAuth('login'));
document.querySelectorAll('input[name="circleVerificationMethod"]').forEach(input=>input.addEventListener('change',()=>{const method=document.querySelector('input[name="circleVerificationMethod"]:checked').value;document.querySelectorAll('[data-contact]').forEach(label=>label.hidden=label.dataset.contact!==method)}));
profileForm.addEventListener('submit',async event=>{event.preventDefault();const status=document.getElementById('circleAuthStatus'),password=document.getElementById('circlePassword').value,confirmPassword=document.getElementById('circlePasswordConfirm').value,method=document.querySelector('input[name="circleVerificationMethod"]:checked').value,email=document.getElementById('circleEmail').value.trim(),mobile=document.getElementById('circlePhone').value.trim();if(!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).{12,}$/.test(password)){status.textContent='Your password must meet all five security requirements.';return}if(password!==confirmPassword){status.textContent='The passwords do not match.';return}if(method==='email'&&!email){status.textContent='Enter the email address you want to verify.';return}if(method==='mobile'&&!mobile){status.textContent='Enter the mobile number you want to verify.';return}const payload={givenName:document.getElementById('circleGivenName').value.trim().slice(0,60),familyName:document.getElementById('circleFamilyName').value.trim().slice(0,60),displayName:document.getElementById('circleName').value.trim().slice(0,60),handle:document.getElementById('circleHandle').value.trim().replace(/^@/,'').slice(0,30),birthDate:document.getElementById('circleBirthDate').value,homeCountry:document.getElementById('circleHome').value.trim().slice(0,60),role:document.getElementById('circleRole').value,bio:document.getElementById('circleBio').value.trim().slice(0,240),verificationMethod:method,email:method==='email'?email:'',mobile:method==='mobile'?mobile:'',password,acceptedTerms:true,acceptedPrivacy:true,acceptedGuidelines:true};status.textContent='Creating your secure account…';event.submitter.disabled=true;try{const result=await authRequest('register',payload);pendingRegistration={...payload,registrationId:result.registrationId};profileForm.hidden=true;verificationForm.hidden=false;document.getElementById('circleVerificationDestination').textContent=`We sent a code to ${result.maskedDestination||'your chosen contact'}.`;document.getElementById('circleVerificationCode').focus()}catch(error){status.textContent=error.message}finally{event.submitter.disabled=false}});
verificationForm.addEventListener('submit',async event=>{event.preventDefault();const status=document.getElementById('circleVerificationStatus');if(!pendingRegistration){status.textContent='Start account creation again to request a new code.';return}status.textContent='Verifying…';event.submitter.disabled=true;try{const result=await authRequest('verify',{registrationId:pendingRegistration.registrationId,code:document.getElementById('circleVerificationCode').value});if(result.verified!==true)throw new Error('The code could not be verified.');const profile={id:result.member?.id||'',name:result.member?.displayName||pendingRegistration.displayName,handle:result.member?.handle||pendingRegistration.handle,role:pendingRegistration.role,home:pendingRegistration.homeCountry,bio:pendingRegistration.bio,verified:true,createdAt:new Date().toISOString()};write(PROFILE_KEY,profile);pendingRegistration=null;showProfile(profile)}catch(error){status.textContent=error.message}finally{event.submitter.disabled=false}});
document.getElementById('circleResendCode').addEventListener('click',async()=>{const status=document.getElementById('circleVerificationStatus');if(!pendingRegistration){status.textContent='Start account creation again to request a code.';return}try{await authRequest('resend',{registrationId:pendingRegistration.registrationId});status.textContent='A new code has been sent.'}catch(error){status.textContent=error.message}});document.getElementById('circleChangeContact').addEventListener('click',()=>showAuth('create'));
loginForm.addEventListener('submit',async event=>{event.preventDefault();const status=document.getElementById('circleLoginStatus');status.textContent='Signing in…';event.submitter.disabled=true;try{const result=await authRequest('login',{identifier:document.getElementById('circleLoginIdentifier').value.trim(),password:document.getElementById('circleLoginPassword').value});if(!result.member)throw new Error('Your account details could not be loaded.');const profile={id:result.member.id||'',name:result.member.displayName,handle:result.member.handle||'',role:result.member.role||'Safari traveller',home:result.member.homeCountry||'',bio:result.member.bio||'',verified:result.member.verified===true,createdAt:result.member.createdAt||new Date().toISOString()};write(PROFILE_KEY,profile);showProfile(profile)}catch(error){status.textContent=error.message}finally{event.submitter.disabled=false}});
document.getElementById('circleRecoveryButton').addEventListener('click',async()=>{const identifier=document.getElementById('circleLoginIdentifier').value.trim(),status=document.getElementById('circleLoginStatus');if(!identifier){status.textContent='Enter your email, mobile number or handle first.';return}try{await authRequest('recover',{identifier});status.textContent='Recovery instructions have been sent to your verified contact.'}catch(error){status.textContent=error.message}});
document.getElementById('circleEditProfile').addEventListener('click',editProfile);
document.getElementById('circleDeleteData').addEventListener('click',()=>{if(!confirm('Remove your Safari Circle profile and posts from this device?'))return;localStorage.removeItem(PROFILE_KEY);localStorage.removeItem(POSTS_KEY);localStorage.removeItem(INTERESTS_KEY);profileForm.reset();showAuth()});
document.querySelectorAll('[data-circle-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-circle-tab]').forEach(item=>item.classList.toggle('selected',item===button));document.querySelectorAll('[data-circle-panel]').forEach(panel=>panel.hidden=panel.dataset.circlePanel!==button.dataset.circleTab)}));
function processImage(file){return new Promise((resolve,reject)=>{if(!file){resolve('');return}if(file.size>8*1024*1024){reject(new Error('Choose an image smaller than 8 MB.'));return}const reader=new FileReader();reader.onerror=()=>reject(new Error('The photograph could not be read.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('The selected file is not a usable photograph.'));image.onload=()=>{const scale=Math.min(1,1280/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.8))};image.src=reader.result};reader.readAsDataURL(file)})}
document.getElementById('circlePostForm').addEventListener('submit',async event=>{event.preventDefault();const status=document.getElementById('circleFormStatus'),button=event.target.querySelector('.circle-publish');button.disabled=true;status.textContent='Preparing your field post…';try{const image=await processImage(document.getElementById('circlePostImage').files[0]),sensitive=document.getElementById('circleSensitive').checked,post={id:crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`,author:getProfile().name,role:getProfile().role,type:document.getElementById('circlePostType').value,species:document.getElementById('circleSpecies').value.trim().slice(0,90),country:document.getElementById('circleCountry').value.trim().slice(0,60),place:sensitive?'':document.getElementById('circlePlace').value.trim().slice(0,100),locationProtected:sensitive,text:document.getElementById('circlePostText').value.trim().slice(0,1800),visibility:document.getElementById('circleVisibility').value,image,liked:false,comments:[],createdAt:new Date().toISOString()};const posts=getPosts();posts.unshift(post);write(POSTS_KEY,posts.slice(0,100));event.target.reset();document.getElementById('circleSensitive').checked=true;status.textContent='Published to your Safari Circle.';fetch('/api/circle/posts',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify(post)}).catch(()=>{});renderFeed()}catch(error){status.textContent=error.message||'The post could not be saved.'}finally{button.disabled=false}});
function postCard(post){const when=new Date(post.createdAt).toLocaleString(),place=post.locationProtected?(post.country?`${post.country} · specific location protected`:'Specific location protected'):[post.place,post.country].filter(Boolean).join(', '),comments=Array.isArray(post.comments)?post.comments:[];return `<article class="circle-post" data-circle-post="${safe(post.id)}"><header class="circle-post-head"><span class="circle-post-avatar">${safe(initials(post.author))}</span><div><strong>${safe(post.author)}</strong><small>${safe(post.role)} · ${safe(when)}</small></div><span class="circle-post-type">${safe(post.type)}</span></header><div class="circle-post-body"><p>${safe(post.text)}</p><div class="circle-post-tags">${post.species?`<span>◎ ${safe(post.species)}</span>`:''}${place?`<span>⌖ ${safe(place)}</span>`:''}<span>${post.visibility==='private'?'🔒 Only me':post.visibility==='followers'?'◉ Followers':'◎ Public'}</span></div></div>${post.image?`<img src="${post.image}" alt="Photograph shared with this field post">`:''}<div class="circle-post-actions"><button type="button" data-like-post class="${post.liked?'active':''}">${post.liked?'♥ Appreciated':'♡ Appreciate'}</button><button type="button" data-toggle-comments>▱ ${comments.length} ${comments.length===1?'comment':'comments'}</button><button type="button" data-delete-post>Remove</button></div><div class="circle-comments" hidden>${comments.map(comment=>`<p class="circle-comment"><strong>${safe(comment.author)}</strong> ${safe(comment.text)}</p>`).join('')}<form class="circle-comment-form"><input maxlength="300" required placeholder="Add a constructive comment"><button>Post</button></form></div></article>`}
function renderFeed(){const filter=document.getElementById('circleFeedFilter').value,posts=getPosts().filter(post=>filter==='all'||post.type===filter);feed.innerHTML=posts.length?posts.map(postCard).join(''):'<div class="circle-empty"><strong>Your field feed is ready.</strong><p>Share a sighting, question, photograph, film note or safari story.</p></div>'}
document.getElementById('circleFeedFilter').addEventListener('change',renderFeed);
feed.addEventListener('click',event=>{const card=event.target.closest('[data-circle-post]');if(!card)return;const posts=getPosts(),post=posts.find(item=>item.id===card.dataset.circlePost);if(!post)return;if(event.target.closest('[data-like-post]'))post.liked=!post.liked;else if(event.target.closest('[data-toggle-comments]')){card.querySelector('.circle-comments').hidden=!card.querySelector('.circle-comments').hidden;return}else if(event.target.closest('[data-delete-post]')){if(!confirm('Remove this post from the device?'))return;write(POSTS_KEY,posts.filter(item=>item.id!==post.id));renderFeed();return}else return;write(POSTS_KEY,posts);renderFeed()});
feed.addEventListener('submit',event=>{const form=event.target.closest('.circle-comment-form');if(!form)return;event.preventDefault();const card=form.closest('[data-circle-post]'),posts=getPosts(),post=posts.find(item=>item.id===card.dataset.circlePost),text=form.querySelector('input').value.trim();if(!post||!text)return;post.comments=Array.isArray(post.comments)?post.comments:[];post.comments.push({author:getProfile().name,text:text.slice(0,300),createdAt:new Date().toISOString()});write(POSTS_KEY,posts);renderFeed()});
const interestBox=document.getElementById('circleInterests');function renderInterests(){const followed=new Set(read(INTERESTS_KEY,[]));interestBox.innerHTML=interests.map(item=>`<button type="button" aria-pressed="${followed.has(item)}" data-circle-interest="${safe(item)}">${followed.has(item)?'✓ ':''}${safe(item)}</button>`).join('')}interestBox.addEventListener('click',event=>{const button=event.target.closest('[data-circle-interest]');if(!button)return;const followed=new Set(read(INTERESTS_KEY,[]));followed.has(button.dataset.circleInterest)?followed.delete(button.dataset.circleInterest):followed.add(button.dataset.circleInterest);write(INTERESTS_KEY,[...followed]);renderInterests()});renderInterests();
const profile=getProfile();if(profile)showProfile(profile);else showAuth()
})();
